-- 教育行业生产参考数据。
--
-- 仅包含字典定义、菜单定义和权限定义，不包含学校、组织、账号、教师、
-- 学生、班级、课程、流程实例等租户业务数据或演示数据。主键来自已验收的
-- ChronosEducation 实例，全部为真实 UUID。先装载临时参考集，再按业务自然键
-- 合并，兼容相同定义使用不同 UUID 的既有实例。

BEGIN;

SELECT pg_advisory_xact_lock(hashtext('education-reference-data-v20260912'));

CREATE TEMP TABLE tmp_education_ref_dict
    (LIKE public.t_dict INCLUDING DEFAULTS)
    ON COMMIT DROP;

CREATE TEMP TABLE tmp_education_ref_menu
    (LIKE public.t_menu INCLUDING DEFAULTS)
    ON COMMIT DROP;

CREATE TEMP TABLE tmp_education_ref_permission
    (LIKE public.t_permission INCLUDING DEFAULTS)
    ON COMMIT DROP;


-- 字典先合并根节点，再把子项关联到目标实例实际使用的根节点 UUID。
    id, create_by, create_time, last_update_by, last_update_time,
    dict_code, dict_name, dict_value, parent_id, status)
SELECT reference.id, 'SYSTEM', CURRENT_TIMESTAMP, 'SYSTEM', CURRENT_TIMESTAMP,
       reference.dict_code, reference.dict_name, reference.dict_value,
       reference.parent_id, reference.status
FROM tmp_education_ref_dict reference
WHERE COALESCE(reference.parent_id, '') = ''
  AND NOT EXISTS (
      SELECT 1
      FROM public.t_dict existing
      WHERE existing.dict_code = reference.dict_code
        AND COALESCE(existing.parent_id, '') = '')
ON CONFLICT (id) DO NOTHING;

    id, create_by, create_time, last_update_by, last_update_time,
    dict_code, dict_name, dict_value, parent_id, status)
SELECT reference.id, 'SYSTEM', CURRENT_TIMESTAMP, 'SYSTEM', CURRENT_TIMESTAMP,
       reference.dict_code, reference.dict_name, reference.dict_value,
       actual_parent.id, reference.status
FROM tmp_education_ref_dict reference
JOIN tmp_education_ref_dict source_parent
  ON source_parent.id = reference.parent_id
JOIN public.t_dict actual_parent
  ON actual_parent.dict_code = source_parent.dict_code
 AND COALESCE(actual_parent.parent_id, '') = ''
WHERE COALESCE(reference.parent_id, '') <> ''
  AND NOT EXISTS (
      SELECT 1
      FROM public.t_dict existing
      WHERE existing.dict_code = reference.dict_code
        AND COALESCE(existing.dict_value, '') = COALESCE(reference.dict_value, '')
        AND COALESCE(existing.parent_id, '') <> '')
ON CONFLICT (id) DO NOTHING;

-- 菜单通过路径或同级名称识别自然键，并建立源 UUID 到目标 UUID 的映射。
CREATE TEMP TABLE tmp_education_menu_map (
    source_id varchar(64) PRIMARY KEY,
    target_id varchar(64) NOT NULL)
ON COMMIT DROP;

    id, create_by, create_time, last_update_by, last_update_time,
    menu_name, order_num, parent_id, path)
SELECT reference.id, 'SYSTEM', CURRENT_TIMESTAMP, 'SYSTEM', CURRENT_TIMESTAMP,
       reference.menu_name, reference.order_num, reference.parent_id, reference.path
FROM tmp_education_ref_menu reference
WHERE COALESCE(reference.parent_id, '') = ''
  AND NOT EXISTS (
      SELECT 1
      FROM public.t_menu existing
      WHERE COALESCE(existing.parent_id, '') = ''
        AND ((COALESCE(reference.path, '') <> '' AND existing.path = reference.path)
          OR (COALESCE(reference.path, '') = '' AND existing.menu_name = reference.menu_name)))
ON CONFLICT (id) DO NOTHING;

SELECT reference.id, existing.id
FROM tmp_education_ref_menu reference
JOIN public.t_menu existing
  ON COALESCE(existing.parent_id, '') = ''
 AND ((COALESCE(reference.path, '') <> '' AND existing.path = reference.path)
   OR (COALESCE(reference.path, '') = '' AND existing.menu_name = reference.menu_name))
WHERE COALESCE(reference.parent_id, '') = '';

    id, create_by, create_time, last_update_by, last_update_time,
    menu_name, order_num, parent_id, path)
SELECT reference.id, 'SYSTEM', CURRENT_TIMESTAMP, 'SYSTEM', CURRENT_TIMESTAMP,
       reference.menu_name, reference.order_num, parent_map.target_id, reference.path
FROM tmp_education_ref_menu reference
JOIN tmp_education_menu_map parent_map
  ON parent_map.source_id = reference.parent_id
WHERE COALESCE(reference.parent_id, '') <> ''
  AND NOT EXISTS (
      SELECT 1
      FROM public.t_menu existing
      WHERE existing.parent_id = parent_map.target_id
        AND ((COALESCE(reference.path, '') <> '' AND existing.path = reference.path)
          OR (COALESCE(reference.path, '') = '' AND existing.menu_name = reference.menu_name)))
ON CONFLICT (id) DO NOTHING;

SELECT reference.id, existing.id
FROM tmp_education_ref_menu reference
JOIN tmp_education_menu_map parent_map
  ON parent_map.source_id = reference.parent_id
JOIN public.t_menu existing
  ON existing.parent_id = parent_map.target_id
 AND ((COALESCE(reference.path, '') <> '' AND existing.path = reference.path)
   OR (COALESCE(reference.path, '') = '' AND existing.menu_name = reference.menu_name))
WHERE COALESCE(reference.parent_id, '') <> '';

-- 权限编码是跨实例稳定键；菜单型权限改写为目标实例真实菜单 UUID。
    id, create_by, create_time, last_update_by, last_update_time,
    action_type, built_in, config_json, description, http_method, menu_id,
    permission_code, permission_name, permission_type, resource_pattern,
    resource_type, scope_type, status)
SELECT reference.id, 'SYSTEM', CURRENT_TIMESTAMP, 'SYSTEM', CURRENT_TIMESTAMP,
       reference.action_type, reference.built_in, reference.config_json,
       reference.description, reference.http_method, menu_map.target_id,
       reference.permission_code, reference.permission_name,
       reference.permission_type, reference.resource_pattern,
       reference.resource_type, reference.scope_type, reference.status
FROM tmp_education_ref_permission reference
LEFT JOIN tmp_education_menu_map menu_map
  ON menu_map.source_id = reference.menu_id
WHERE NOT EXISTS (
    SELECT 1
    FROM public.t_permission existing
    WHERE existing.permission_code = reference.permission_code)
ON CONFLICT (permission_code) DO NOTHING;

COMMIT;
